/* Vendored HTMX compatibility loader for the Elisa lab. */
(function(){if(window.htmx)return;window.htmx={trigger:function(){},ajax:function(method,url,o){return fetch(url,{method:method||'GET',credentials:'same-origin',headers:(o&&o.headers)||{}}).then(function(r){return r.text()}).then(function(html){var e=document.querySelector(o&&o.target);if(e)e.innerHTML=html})}};document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('[hx-get]').forEach(function(e){var load=function(){fetch(e.getAttribute('hx-get'),{credentials:'same-origin'}).then(function(r){return r.text()}).then(function(h){e.innerHTML=h})};if((e.getAttribute('hx-trigger')||'').indexOf('load')>=0)load();var m=(e.getAttribute('hx-trigger')||'').match(/every (\d+)s/);if(m)setInterval(load,+m[1]*1000)})})})();
